                    Math.abs(line.left - center) <= START_TOLERANCE ||
                    line.innerStarts.some((boundary: any) => Math.abs(boundary.x - center) <= START_TOLERANCE);
                  const crosses = line.left < center - START_TOLERANCE && line.right > center + START_TOLERANCE;

